// ============ N2 localStorage PROGRESS SYSTEM ============
const N2_STORAGE_KEY = 'classe_n2_progress';

export function getClasseN2Progress(): ClasseProgress {
  try {
    const raw = localStorage.getItem(N2_STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      return {
        completedLessons: parsed.completedLessons || [],
        lessonStars: parsed.lessonStars || {},
        tabsCompleted: parsed.tabsCompleted || {},
        evaluationScores: parsed.evaluationScores || {},
        evaluationBest: parsed.evaluationBest || {},
        calculScores: parsed.calculScores || {},
        calculAnswers: parsed.calculAnswers || {},
        lastLesson: parsed.lastLesson || 0,
        themeBadges: parsed.themeBadges || [],
      };
    }
  } catch {}
  return { completedLessons: [], lessonStars: {}, tabsCompleted: {}, evaluationScores: {}, evaluationBest: {}, calculScores: {}, calculAnswers: {}, lastLesson: 0, themeBadges: [] };
}

function saveN2Progress(p: ClasseProgress) {
  localStorage.setItem(N2_STORAGE_KEY, JSON.stringify(p));
}

export function markN2TabComplete(lessonId: number, tab: string) {
  const p = getClasseN2Progress();
  p.tabsCompleted[`lesson_${lessonId}_${tab}`] = true;
  const lesson = CLASSE_N2_LESSONS.find(l => l.id === lessonId);
  if (lesson) {
    const allTabs = ['text', 'observe', 'ecoute', 'reagis', 'retiens', 'phonetics'];
    const activeTabs = allTabs.filter(t => {
      if (t === 'text') return true;
      if (t === 'phonetics') return !!lesson.phonetics;
      return (lesson.sections as any)[t]?.length > 0;
    });
    const completedCount = activeTabs.filter(t => p.tabsCompleted[`lesson_${lessonId}_${t}`]).length;
    p.lessonStars[lessonId] = Math.min(5, completedCount);
  }
  saveN2Progress(p);
}

export function markN2LessonComplete(id: number) {
  const p = getClasseN2Progress();
  if (!p.completedLessons.includes(id)) p.completedLessons.push(id);
  p.lastLesson = id;
  saveN2Progress(p);
}

export function saveN2EvaluationScore(evalId: number, score: number) {
  const p = getClasseN2Progress();
  p.evaluationScores[evalId] = score;
  if (!p.evaluationBest[evalId] || score > p.evaluationBest[evalId]) {
    p.evaluationBest[evalId] = score;
  }
  saveN2Progress(p);
}

export function saveN2CalculScore(lessonId: number, score: number, total: number) {
  const p = getClasseN2Progress();
  p.calculScores[lessonId] = { score, total };
  saveN2Progress(p);
}

export function getN2LessonStars(lessonId: number): number {
  return getClasseN2Progress().lessonStars[lessonId] || 0;
}

export function isN2LessonUnlocked(lessonId: number): boolean {
  if (lessonId <= 1) return true;
  const p = getClasseN2Progress();
  const prevLesson = CLASSE_N2_LESSONS.find(l => l.id === lessonId - 1);
  if (!prevLesson) return true;
  return (p.lessonStars[lessonId - 1] || 0) >= 2 || p.completedLessons.includes(lessonId - 1);
}
